def priority(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""
    # Dynamic weighted combination: balance between future space needs, average ID, and future blocking potential
    space_factor = EMP / (SH + 1)
    avg_factor = -AVG * 2
    future_block_factor = -RI / (SH + 1)
    diff_factor = DIFF / 1000000
    alignment_factor = (CUR - AVG) / (SH + 1)

    # Adjust weights based on space availability and future blockage potential
    if space_factor > 0.4:
        space_weight = 0.9
    elif space_factor > 0.2:
        space_weight = 0.6
    else:
        space_weight = 0.3

    if future_block_factor < -0.3:
        future_weight = 0.8
    elif future_block_factor < -0.1:
        future_weight = 0.5
    else:
        future_weight = 0.2

    priority = (space_factor * space_weight) + (avg_factor) + (future_block_factor * future_weight) + (diff_factor * 0.3) + (alignment_factor * 0.1)
    return priority
